import {World,Progress,items,drop,blockNames,recipes,quests,validateSave,HALF,WATER,hash,terrainHeight} from './core.js';
import {Renderer,T} from './render.js';
const $=s=>document.querySelector(s),SAVE='verdant.save.v1',OPTIONS='verdant.options.v1';
let settings={quality:'high',fov:70,sensitivity:1,volume:.3,mods:{wild:true,ruins:true,builder:false},custom:{name:'标准规则',gatheringMultiplier:1,dayLength:1200,enemyDamage:1}};
try{const s=JSON.parse(localStorage.getItem(OPTIONS)||'null');if(s)settings={...settings,...s,mods:{...settings.mods,...s.mods},custom:{...settings.custom,...s.custom}}}catch{}
let world,view,progress=new Progress(),state='home',panel='',player={x:-8,y:15,z:24,vy:0,yaw:0,pitch:0,ground:false},keys={},time=400,elapsed=0,selected=0,hit=null,mineTime=0,mineKey='',mouseDown=false,attackCooldown=0,saveTick=0,hudTick=0,lastStage=0,damageCooldown=0,boss=null,mobs=[],hazards=[],initialized=false,last=performance.now(),swing=0,lastMobTick=0;
let audioContext,master,wind;const hotbar=['pick','sword','wood','stone','plank','brick','torch','food','dirt'];
function sound(freq=400,duration=.08,type='sine',gain=.1){if(!audioContext||settings.volume===0)return;const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,freq*.5),audioContext.currentTime+duration);g.gain.setValueAtTime(gain,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+duration);o.connect(g);g.connect(master);o.start();o.stop(audioContext.currentTime+duration)}
function initAudio(){try{if(!audioContext){audioContext=new (window.AudioContext||window.webkitAudioContext)();master=audioContext.createGain();master.gain.value=settings.volume;master.connect(audioContext.destination);const buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.035;wind=audioContext.createBufferSource();wind.buffer=buffer;wind.loop=true;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=350;wind.connect(filter);filter.connect(master);wind.start()}audioContext.resume()}catch{}}
function toast(text,error=false){const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=text;$('#toasts').append(e);while($('#toasts').children.length>3)$('#toasts').firstElementChild.remove();setTimeout(()=>e.remove(),4500)}
function icon(id){const d=items[id];return d.icon?`<span class="toolicon" style="color:${d.color}">${d.icon}</span>`:`<span class="cubeicon" style="--block:${d.color}"></span>`}
function safeText(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function persistSettings(){try{localStorage.setItem(OPTIONS,JSON.stringify(settings))}catch{toast('浏览器未允许保存设置',true)}}
function hasSave(){try{return !!localStorage.getItem(SAVE)}catch{return false}}
function updateHome(){const yes=hasSave();$('#continue').disabled=!yes;$('#savehint').textContent=yes?'已发现本地存档 · 继续属于你的旅程':'无需下载 · 本地自动存档 · 键盘与鼠标操作'}
function makeSave(){return {version:1,seed:world.seed,progress:progress.serialize(),position:{x:player.x,y:player.y,z:player.z,yaw:player.yaw,pitch:player.pitch},edits:world.edits,time,elapsed,bossHealth:boss?.health,mods:settings.mods,custom:settings.custom,savedAt:Date.now()}}
function save(quiet=true){if(!initialized||state==='home'||state==='tour')return;try{localStorage.setItem(SAVE,JSON.stringify(makeSave()));if(!quiet)toast('旅程已保存');updateHome()}catch{toast('自动存档失败，请在暂停菜单导出存档。',true)}}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000)}
function resetActors(){for(const m of mobs)view.scene.remove(m.mesh);mobs=[];if(boss)view.scene.remove(boss.mesh);boss=null;for(const h of hazards){view.scene.remove(h.mesh);h.mesh.geometry.dispose();h.mesh.material.dispose()}hazards=[]}
function spawnMobs(){if(progress.dimension==='end')return;for(let i=0;i<14;i++){let x=-40+hash(i,11)*80,z=-40+hash(i,33)*80;const y=world.top(x,z);if(y>WATER&&Math.hypot(x-player.x,z-player.z)>8){const mesh=view.createMob();mesh.position.set(x,y,z);mobs.push({mesh,x,y,z,hp:48,cool:0,phase:i,aggro:false})}}}
function spawnBoss(hp=192){if(progress.won)return;const mesh=view.createMob('boss');boss={mesh,health:Number.isFinite(hp)?Math.max(1,Math.min(192,hp)):192,t:0,phase:0,target:{x:0,z:0},hazardTimer:3};mesh.position.set(0,7,0);$('#bossbar').hidden=false}
function startNew(){progress=new Progress();world=new World();view.world=world;view.rebuild();view.portal.position.y=world.gateY+3.5;time=400;elapsed=0;player={x:-8,y:world.top(-8,24)+.1,z:24,vy:0,yaw:-.2,pitch:0,ground:false};resetActors();view.setDimension('overworld');spawnMobs();lastStage=0;enterPlay();save();toast('欢迎来到原野。先从身边的树木开始。')}
function loadSave(data){try{const s=validateSave(data);progress=new Progress(s.progress);world=new World(s.seed);world.applyEdits(s.edits);view.world=world;view.rebuild();time=Number.isFinite(s.time)?s.time:400;elapsed=Number.isFinite(s.elapsed)?s.elapsed:0;player={...s.position,x:Math.max(-53,Math.min(53,s.position.x)),z:Math.max(-53,Math.min(53,s.position.z)),y:Math.max(1,Math.min(60,s.position.y)),yaw:s.position.yaw||0,pitch:Math.max(-1.5,Math.min(1.5,s.position.pitch||0)),vy:0,ground:false};lastStage=progress.stage;resetActors();view.setDimension(progress.dimension);if(progress.dimension==='end')spawnBoss(s.bossHealth);else spawnMobs();enterPlay();if(progress.health<=0)openPanel('death');else if(progress.won&&progress.dimension==='end')openPanel('win');toast('欢迎回来，旅人。')}catch(e){toast('无法读取存档：'+e.message,true)}}
function enterPlay(){state='play';panel='';$('#modal').hidden=true;$('#home').hidden=true;$('#hud').hidden=false;$('#tourhud').hidden=true;$('#shade').style.opacity=0;view.hand.visible=true;keys={};mouseDown=false;updateHUD();lockPointer();initAudio()}
function lockPointer(){try{const p=$('#world').requestPointerLock?.();if(p?.catch)p.catch(()=>toast('点击游戏画面控制视角；若浏览器不允许锁定，可按住鼠标中键拖动。'))}catch{}}
function openPanel(name){if(state==='play'){save();state='paused';mouseDown=false;keys={};document.exitPointerLock?.()}panel=name;$('#modal').hidden=false;renderPanel();}
function closePanel(){if(panel==='death'||panel==='win')return;$('#modal').hidden=true;panel='';if(state==='paused')enterPlay()}
function returnHome(){save();state='home';$('#modal').hidden=true;$('#hud').hidden=true;$('#bossbar').hidden=true;$('#home').hidden=false;$('#shade').style.opacity=1;view.hand.visible=false;view.outline.visible=false;view.setDimension('overworld');for(const m of mobs)m.mesh.visible=false;if(boss)boss.mesh.visible=false;updateHome();document.exitPointerLock?.()}
const chaptersHTML=()=>quests.map(([title,desc],i)=>`<div class="chapter ${i<progress.stage?'done':i===progress.stage?'active':''}"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${title}${i<progress.stage?' ✓':''}</h3><p>${desc}</p></div></div>`).join('');
function renderPanel(){const c=$('#modalcontent');$('#closemodal').hidden=panel==='death'||panel==='win';if(panel==='inventory'){c.innerHTML=`<div class="panel-head">INVENTORY & CRAFTING</div><h2>行囊与手作</h2><p class="sub">采集的每一样东西，都有新的可能。合成后按数字键选择工具或方块。</p><div class="two-col"><div><h3>随身物品</h3><div class="inventory-grid">${Object.entries(items).map(([id,d])=>`<div class="inv-item" title="${d.name}">${icon(id)}<span>${d.name}</span><b>${progress.inventory[id]||0}</b></div>`).join('')}</div><p class="notice">工具不会损坏。熔炉保留在背包即可熔炼。选择浆果后按 F 恢复生命和饱食。</p></div><div><h3>合成配方</h3>${recipes.map(r=>`<div class="recipe">${icon(r.id)}<div><strong>${items[r.id].name}${r.out>1?' × '+r.out:''}</strong><small>${Object.entries(r.cost).map(([id,n])=>`${items[id].name} ${n}`).join(' · ')}${r.need?' · 需熔炉':''}</small><small>${r.text}</small></div><button data-craft="${r.id}" ${progress.canCraft(r)?'':'disabled'}>合成</button></div>`).join('')}</div></div>`;c.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{const id=b.dataset.craft;if(progress.craft(id)){if(settings.mods.builder&&['plank','brick','torch'].includes(id))progress.add(id,recipes.find(r=>r.id===id).out);sound(600,.12);toast('获得 '+items[id].name);updateHUD();renderPanel();save()}})}
 else if(panel==='guide'||panel==='journal'){c.innerHTML=`<div class="panel-head">A FIELD GUIDE TO YOUR WORLD</div><h2>写下你的冒险</h2><p class="sub">一段可完成的独立生存旅程。森林、矿场、遗迹与星门，都在这座 112 × 112 格的河谷里。</p><div class="two-col"><div>${chaptersHTML()}</div><div><h3>探索与操作</h3><div class="keygrid"><span><kbd>WASD</kbd> 移动</span><span><kbd>鼠标</kbd> 环顾四周</span><span><kbd>空格</kbd> 跳跃 / 游泳</span><span><kbd>Shift</kbd> 奔跑</span><span><kbd>左键长按</kbd> 采集</span><span><kbd>右键</kbd> 放置方块</span><span><kbd>1–9 / 滚轮</kbd> 快捷栏</span><span><kbd>E</kbd> 背包 / 合成</span><span><kbd>F</kbd> 食用 / 星门</span><span><kbd>J</kbd> 冒险手册</span><span><kbd>Esc</kbd> 暂停 / 设置</span><span><kbd>R</kbd> 返回出生点</span></div><h3>旅人的地图</h3><p class="notice">出生地：X −8 / Z 24<br>露天矿场：X −17 / Z 14；X 21 / Z 8<br>水晶遗迹：X −24 / Z 3；X 24 / Z −15；X −20 / Z −30<br>北方星门：X 0 / Z −30<br>左上角任务会自动追踪进度，屏幕下方显示坐标。</p><h3>在荒野活下去</h3><p class="sub">长按采集需要保持瞄准；石镐能开采矿石。树叶可以制作浆果。饱食充足时生命会缓慢恢复。靠近苔原史莱姆时请保持警惕。死亡会保留所有物品并在安全地点重生。</p><p class="sub">推荐电脑浏览器与键鼠。原创世界、规则和扩展，不支持 Minecraft Java / Bedrock 模组文件。</p><button class="smallbtn" data-about>素材与制作说明 ↗</button></div></div>`;c.querySelector('[data-about]').onclick=()=>{panel='about';renderPanel()}}
 else if(panel==='mods'){c.innerHTML=`<div class="panel-head">MAKE THE WORLD YOUR OWN</div><h2>模组工坊 <span class="pill">原创扩展</span></h2><p class="sub">即开即用的内置玩法扩展，可随时切换。自定义包使用安全的 JSON 规则格式。</p>${[['wild','丰饶原野','树叶掉落更多浆果，饱食消耗减半。'],['ruins','古代遗产','采集遗迹水晶时额外获得铁锭。'],['builder','匠人之手','木板、石砖和萤石合成产量翻倍。']].map(([id,title,text])=>`<label class="mod-row"><div><strong>${title}</strong><small>${text}</small></div><input type="checkbox" data-mod="${id}" ${settings.mods[id]?'checked':''}></label>`).join('')}<div class="setting-row"><div>自定义规则包<small id="packname">当前：${safeText(settings.custom.name)} · 采集 ×${settings.custom.gatheringMultiplier} · 昼夜 ${settings.custom.dayLength} 秒</small></div><button class="smallbtn" id="importmod">导入 JSON</button></div><div class="modal-actions"><button class="secondary" id="samplemod">下载规则模板 ↓</button><button class="secondary" id="resetmod">恢复标准规则</button></div><p class="notice">支持采集倍率、昼夜时长和敌人伤害倍率。不执行脚本，不兼容 .jar / .mcaddon。</p>`;c.querySelectorAll('[data-mod]').forEach(b=>b.onchange=()=>{settings.mods[b.dataset.mod]=b.checked;persistSettings();toast('扩展设置已生效')});$('#samplemod').onclick=()=>download('verdant-mod-template.json',{name:'悠闲探险',gatheringMultiplier:2,dayLength:1800,enemyDamage:.7});$('#resetmod').onclick=()=>{settings.custom={name:'标准规则',gatheringMultiplier:1,dayLength:1200,enemyDamage:1};persistSettings();renderPanel()};$('#importmod').onclick=()=>chooseFile(async text=>{const m=JSON.parse(text);if(typeof m.name!=='string'||m.name.length>40||!Number.isInteger(m.gatheringMultiplier)||m.gatheringMultiplier<1||m.gatheringMultiplier>5||!Number.isFinite(m.dayLength)||m.dayLength<300||m.dayLength>2400||!Number.isFinite(m.enemyDamage)||m.enemyDamage<.25||m.enemyDamage>3)throw Error('请使用规则模板：倍率 1–5，昼夜 300–2400 秒，伤害 0.25–3。');settings.custom={name:m.name,gatheringMultiplier:m.gatheringMultiplier,dayLength:m.dayLength,enemyDamage:m.enemyDamage};persistSettings();renderPanel();toast('规则包已启用')})}
 else if(panel==='settings'){c.innerHTML=`<div class="panel-head">LIGHT, SOUND & ATMOSPHERE</div><h2>让世界恰到好处</h2><p class="sub">写实风光照与体素世界。根据设备性能调整画质，设置立即生效。</p><label class="setting-row"><div>光影质量<small>高画质开启柔和实时阴影；流畅模式关闭阴影。</small></div><select id="quality"><option value="low">流畅</option><option value="high">高画质 · 推荐</option><option value="ultra">超清</option></select></label><label class="setting-row"><div>视野范围<small>更宽的视角，更开阔的旅程。</small></div><input id="fov" type="range" min="55" max="100" value="${settings.fov}"></label><label class="setting-row"><div>鼠标灵敏度</div><input id="sensitivity" type="range" min="0.3" max="2.5" step="0.1" value="${settings.sensitivity}"></label><label class="setting-row"><div>环境与交互音量<small>风声、采集、合成与战斗音效。</small></div><input id="volume" type="range" min="0" max="1" step=".05" value="${settings.volume}"></label><p class="notice">光影包含太阳软阴影、物理材质、接触明暗、远景雾和动态水面高光。没有硬件光线追踪。超清模式需较好的显卡。</p>`;$('#quality').value=settings.quality;$('#quality').onchange=e=>{view.setQuality(e.target.value);persistSettings()};$('#fov').oninput=e=>{settings.fov=+e.target.value;view.camera.fov=settings.fov;view.camera.updateProjectionMatrix();persistSettings()};$('#sensitivity').oninput=e=>{settings.sensitivity=+e.target.value;persistSettings()};$('#volume').oninput=e=>{settings.volume=+e.target.value;initAudio();if(master)master.gain.value=settings.volume;persistSettings()}}
 else if(panel==='pause'){c.innerHTML=`<div class="panel-head">TAKE A MOMENT</div><h2>风景会等你</h2><p class="sub">旅程已自动保存。当前进度：${quests[progress.stage][0]} · 游玩 ${Math.floor(elapsed/60)} 分钟</p><div class="modal-actions"><button class="primary" id="resume">继续旅程 →</button><button class="secondary" data-open="settings">画面与声音</button><button class="secondary" data-open="mods">模组工坊</button><button class="secondary" data-open="guide">冒险指南</button></div><div class="modal-actions"><button class="smallbtn" id="export">导出存档 ↓</button><button class="smallbtn" id="import">导入存档 ↑</button><button class="smallbtn" id="backhome">保存并返回首页</button></div><p class="notice">存档保存在当前浏览器。导出文件可备份世界与任务进度；清除浏览器数据会删除本地存档。</p>`;$('#resume').onclick=closePanel;$('#export').onclick=()=>download('原野纪元-旅程存档.json',makeSave());$('#import').onclick=()=>chooseFile(text=>loadSave(validateSave(JSON.parse(text))));$('#backhome').onclick=returnHome;c.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{panel=b.dataset.open;renderPanel()})}
 else if(panel==='new'){c.innerHTML=`<div class="panel-head">A NEW BEGINNING</div><h2>开启新的故事</h2><p class="sub">新的冒险会替换本地自动存档。你可以先下载旧旅程作为备份。</p><div class="modal-actions"><button class="secondary" id="backupold">备份旧旅程 ↓</button><button class="primary" id="confirmnew">创建新世界 →</button></div>`;$('#backupold').onclick=()=>{try{download('原野纪元-备份.json',JSON.parse(localStorage.getItem(SAVE)))}catch{toast('没有可读取的存档',true)}};$('#confirmnew').onclick=startNew}
 else if(panel==='death'){c.innerHTML=`<div class="panel-head">EVERY JOURNEY HAS ANOTHER DAWN</div><h2>在晨光中重新出发</h2><p class="sub">所有物品与主线进度已保留。吃一些浆果，准备好再出发。</p><div class="modal-actions"><button class="primary" id="respawn">安全重生 →</button></div>`;$('#respawn').onclick=()=>{progress.health=100;progress.hunger=80;progress.add('food',3);player.x=progress.dimension==='end'?0:-8;player.z=progress.dimension==='end'?18:24;player.y=progress.dimension==='end'?1:world.top(-8,24)+.1;player.vy=0;damageCooldown=4;enterPlay();save()}}
 else if(panel==='win'){c.innerHTML=`<div class="panel-head center">THE END IS ONLY A BEGINNING</div><div class="endmark">✧</div><h2 class="center">原野，再次迎来黎明。</h2><p class="sub center">虚空之翼已沉睡，星门的光重新连接了世界。<br>你从一块原木出发，完成了属于自己的冒险。</p><div class="notice center">主线通关 · ${Math.floor(elapsed/60)} 分 ${Math.floor(elapsed%60)} 秒<br>你的建筑、物品和旅程将继续保留。</div><div class="modal-actions" style="justify-content:center"><button class="primary" id="afterwin">返回原野，自由建造 ↗</button><button class="secondary" id="winsave">导出通关存档 ↓</button></div><p class="sub center" style="margin-top:25px">VERDANT · 原野纪元<br>献给每一个愿意迈出第一步的旅人。</p>`;$('#afterwin').onclick=()=>{progress.dimension='overworld';view.setDimension('overworld');resetActors();player.x=-8;player.z=24;player.y=world.top(-8,24)+.1;player.vy=0;progress.health=100;progress.hunger=100;spawnMobs();enterPlay();save()};$('#winsave').onclick=()=>download('原野纪元-通关存档.json',makeSave())}
 else if(panel==='about'){c.innerHTML=`<div class="panel-head">MADE FOR THE WANDERERS</div><h2>关于原野纪元</h2><p>原创浏览器体素生存冒险。包含一座可编辑的河谷、采集合成、食物与战斗、三处水晶遗迹、传送星门、最终守卫和通关后自由建造。</p><p class="sub">方块纹理、场景、角色、界面与音效以程序原创制作。森林地表叠加使用 Poly Haven 的 Forest Leaves 02（CC0）。渲染基于 Three.js r170（MIT）。所有运行资源已随站点打包，无需第三方游戏客户端。</p><p><a href="https://polyhaven.com/a/forest_leaves_02" target="_blank" rel="noopener" style="color:var(--lime)">Poly Haven 素材来源 ↗</a>　<a href="vendor/THREE-LICENSE.txt" target="_blank" style="color:var(--lime)">Three.js 许可证 ↗</a></p><p class="notice">这是独立游戏作品，与 Mojang 或 Microsoft 无关联。并非完整 Minecraft 移植；当前为单人有限世界，不包含联网、生物全图鉴、原版红石或第三方 MC 模组运行时。</p>`}}
function chooseFile(fn){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('文件不能超过 10 MB');await fn(await f.text())}catch(e){toast(e.message||'文件读取失败',true)}};input.click()}
function updateHUD(){progress.advance();if(progress.stage!==lastStage){lastStage=progress.stage;toast('旅程更新 · '+quests[progress.stage][0]);sound(850,.25,'sine',.15)}$('#queststep').textContent=String(Math.min(7,progress.stage+1)).padStart(2,'0')+' / 07';$('#questtitle').textContent=quests[progress.stage][0];$('#questdesc').textContent=quests[progress.stage][1];const pct=progress.stage===0?Math.min(1,progress.stats.wood/6):progress.stage===2?Math.min(1,progress.stats.iron/5):progress.stage===6&&boss?1-boss.health/192:0;$('#questprogress').style.width=pct*100+'%';$('#hearts').textContent='♥'.repeat(Math.ceil(progress.health/10))+'♡'.repeat(Math.max(0,10-Math.ceil(progress.health/10)));$('#foodbar').textContent='◆'.repeat(Math.ceil(progress.hunger/10))+'◇'.repeat(Math.max(0,10-Math.ceil(progress.hunger/10)));$('#hotbar').innerHTML=hotbar.map((id,i)=>`<div class="slot ${i===selected?'active':''}" data-slot="${i}" role="button" aria-label="${items[id].name}"><small>${i+1}</small>${icon(id)}<b>${progress.inventory[id]||0}</b></div>`).join('');$('#hotbar').querySelectorAll('[data-slot]').forEach(e=>e.onclick=()=>select(+e.dataset.slot));$('#selectedname').textContent=items[hotbar[selected]].name;view.setTool(progress.inventory[hotbar[selected]]?hotbar[selected]:'');if(boss)$('#bossbar i').style.width=Math.max(0,boss.health/192)*100+'%'}
function select(i){selected=(i+9)%9;mineTime=0;updateHUD()}
function collision(x,y,z){if(progress.dimension==='end')return y<0;for(let bx=Math.floor(x-.28);bx<=Math.floor(x+.28);bx++)for(let by=Math.floor(y+.02);by<=Math.floor(y+1.65);by++)for(let bz=Math.floor(z-.28);bz<=Math.floor(z+.28);bz++)if(world.get(bx,by,bz))return true;return false}
function movePlayer(dt){const moving=keys.KeyW||keys.KeyS||keys.KeyA||keys.KeyD;const swim=progress.dimension==='overworld'&&player.y<WATER-.3;let speed=(keys.ShiftLeft?6.8:4.3)*(swim?.6:1);let f=(keys.KeyW?1:0)-(keys.KeyS?1:0),s=(keys.KeyD?1:0)-(keys.KeyA?1:0);const l=Math.hypot(f,s)||1;f/=l;s/=l;const dx=(-Math.sin(player.yaw)*f+Math.cos(player.yaw)*s)*speed*dt,dz=(-Math.cos(player.yaw)*f-Math.sin(player.yaw)*s)*speed*dt;const bound=progress.dimension==='end'?24.5:54;for(const [axis,delta]of [['x',dx],['z',dz]]){if(!delta)continue;let nx=player.x,nz=player.z;if(axis==='x')nx=Math.max(-bound,Math.min(bound,nx+delta));else nz=Math.max(-bound,Math.min(bound,nz+delta));if(!collision(nx,player.y,nz)){player.x=nx;player.z=nz}else if(player.ground&&!collision(nx,player.y+1.02,nz)&&!collision(player.x,player.y+1.02,player.z)){player.y+=1.02;player.x=nx;player.z=nz}}
 if(keys.Space&&(player.ground||swim)){player.vy=swim?3.5:7.4;player.ground=false}player.vy-=dt*(swim?4:20);player.vy=Math.max(player.vy,swim?-2:-30);const dy=player.vy*dt;let next=player.y+dy;if(collision(player.x,next,player.z)){if(dy<0){if(player.vy< -15)damage((-player.vy-14)*2);player.y=Math.floor(player.y+.01);while(collision(player.x,player.y,player.z)&&player.y<40)player.y+=.05;player.ground=true}player.vy=0}else{player.y=next;player.ground=false}if(player.y< -6)damage(100);view.camera.position.set(player.x,player.y+1.62+(moving&&player.ground?Math.sin(elapsed*11)*.025:0),player.z);view.camera.rotation.set(player.pitch,player.yaw,0);view.hand.position.y=-.38+(moving?Math.sin(elapsed*9)*.014:0)-Math.sin(swing*Math.PI)*.09;view.hand.rotation.x=-Math.sin(swing*Math.PI)*.65;if(swing>0)swing=Math.max(0,swing-dt*3);if(mouseDown&&hit)view.hand.rotation.z=Math.sin(elapsed*19)*.08;else view.hand.rotation.z=0;
 progress.hunger=Math.max(0,progress.hunger-dt*(settings.mods.wild?.018:.036)*(keys.ShiftLeft?2:1));if(progress.hunger>35&&progress.health<100)progress.health=Math.min(100,progress.health+dt*.75);if(progress.hunger===0)progress.health=Math.max(10,progress.health-dt*.5)}
const direction=new T.Vector3();
function raycast(){view.camera.getWorldDirection(direction);const start=view.camera.position,previous={x:Math.floor(start.x),y:Math.floor(start.y),z:Math.floor(start.z)};for(let d=0;d<=6;d+=.04){const x=Math.floor(start.x+direction.x*d),y=Math.floor(start.y+direction.y*d),z=Math.floor(start.z+direction.z*d);const id=progress.dimension==='overworld'?world.get(x,y,z):0;if(id)return {x,y,z,id,previous:{...previous},distance:d};previous.x=x;previous.y=y;previous.z=z}return null}
function gather(dt){hit=raycast();view.outline.visible=!!hit;if(hit){view.outline.position.set(hit.x+.5,hit.y+.5,hit.z+.5);$('#target').textContent=blockNames[hit.id]}else $('#target').textContent='';if(!mouseDown||!hit){mineTime=0;$('#minebar').style.opacity=0;return}const key=`${hit.x},${hit.y},${hit.z}`;if(mineKey!==key){mineKey=key;mineTime=0}if(hit.id===11||hit.id===12){$('#target').textContent='无法破坏 · '+blockNames[hit.id];return}const tool=hotbar[selected],pick=tool==='pick'&&progress.inventory.pick;if((hit.id===7||hit.id===8)&&!pick){$('#target').textContent='需要石镐 · 按 E 合成';return}const dur=hit.id===4?.85:hit.id===5?.25:hit.id===3?pick?.28:.8:hit.id===7||hit.id===8?.9:.38;mineTime+=dt;$('#minebar').style.opacity=1;$('#minebar i').style.width=Math.min(100,mineTime/dur*100)+'%';if(mineTime>=dur){const id=drop[hit.id];if(id){progress.add(id,settings.custom.gatheringMultiplier);if(hit.id===5&&hash(hit.x,hit.z,hit.y)>(settings.mods.wild?.4:.75))progress.add('food',2);if(hit.id===8&&settings.mods.ruins)progress.add('iron',1);toast('+ '+items[id].name+(settings.custom.gatheringMultiplier>1?' × '+settings.custom.gatheringMultiplier:''));view.change(hit.x,hit.y,hit.z,0);sound(100,.12,'triangle',.16);updateHUD()}mineTime=0}}
function place(){if(!hit||progress.dimension!=='overworld')return;const id=hotbar[selected],it=items[id];if(!it.block||!progress.inventory[id]){toast('选择快捷栏里拥有的建筑方块',true);return}const {x,y,z}=hit.previous;if(y<1||y>=39)return;if(Math.abs(x+.5-player.x)<.8&&Math.abs(z+.5-player.z)<.8&&y+1>player.y&&y<player.y+1.7)return;view.change(x,y,z,it.block);progress.inventory[id]--;sound(170,.08,'triangle');updateHUD()}
function attack(){if(attackCooldown>0)return;attackCooldown=.42;swing=1;view.camera.getWorldDirection(direction);const sword=hotbar[selected]==='sword'&&progress.inventory.sword;const dmg=sword?24:6;let nearest=null,dist=5;for(const m of mobs){if(!m.mesh.visible)continue;const v=m.mesh.position.clone().add(new T.Vector3(0,.5,0)).sub(view.camera.position),len=v.length();if(len<dist&&v.normalize().dot(direction)>.72){nearest=m;dist=len}}if(nearest){nearest.hp-=dmg;nearest.aggro=true;nearest.mesh.scale.setScalar(1.15);sound(160,.12,'sawtooth',.07);if(nearest.hp<=0){view.scene.remove(nearest.mesh);mobs=mobs.filter(m=>m!==nearest);progress.add('food',3);progress.stats.kills++;toast('苔原史莱姆被击败 · 浆果 +3');updateHUD()}}if(boss&&!progress.won){const v=boss.mesh.position.clone().sub(view.camera.position);if(v.length()<6&&v.normalize().dot(direction)>.5){boss.health-=dmg;sound(110,.15,'sawtooth',.08);boss.mesh.scale.setScalar(1.06);updateHUD();if(boss.health<=0){progress.won=true;progress.advance();view.scene.remove(boss.mesh);$('#bossbar').hidden=true;for(const h of hazards)view.scene.remove(h.mesh);hazards=[];progress.add('crystal',12);save();openPanel('win')}}}}
function damage(n){if(damageCooldown>0||state!=='play')return;progress.health=Math.max(0,progress.health-n*settings.custom.enemyDamage);damageCooldown=.8;$('#damage').style.opacity=1;setTimeout(()=>$('#damage').style.opacity=0,220);sound(60,.16,'triangle',.15);updateHUD();if(progress.health<=0)openPanel('death')}
function interact(){if(progress.dimension==='overworld'&&Math.hypot(player.x-.5,player.z+29.5)<5.5){if(progress.enter()){resetActors();view.setDimension('end');player={x:0,y:.1,z:18,vy:0,yaw:0,pitch:0,ground:false};progress.health=100;progress.hunger=Math.max(80,progress.hunger);spawnBoss();updateHUD();save();toast('进入终末遗迹。避开红色圆环，等待守卫俯冲！')}else toast('需要星门符印：3 个水晶 + 2 个铁锭，在背包中合成。',true);return}if(hotbar[selected]==='food'&&progress.inventory.food>0){progress.inventory.food--;progress.hunger=Math.min(100,progress.hunger+28);progress.health=Math.min(100,progress.health+18);sound(420,.09);updateHUD();toast('食用浆果 · 生命 +18 / 饱食 +28')}else toast('选择快捷栏 8 的浆果后按 F 食用。')}
function updateMobs(dt){for(const m of mobs){m.cool-=dt;const dist=Math.hypot(player.x-m.x,player.z-m.z);if((dist<8||m.aggro)&&dist>.8&&dist<25){const speed=1.4;m.x+=(player.x-m.x)/dist*dt*speed;m.z+=(player.z-m.z)/dist*dt*speed}const y=world.top(m.x,m.z);m.y+=(y-m.y)*Math.min(1,dt*8);m.mesh.position.set(m.x,m.y+Math.max(0,Math.sin(elapsed*3+m.phase))*.35,m.z);m.mesh.lookAt(player.x,m.mesh.position.y,player.z);m.mesh.scale.lerp(new T.Vector3(1,1,1),dt*8);if(dist<1.35&&Math.abs(player.y-m.y)<2&&m.cool<=0){damage(9);m.cool=1.5}}}
function updateBoss(dt){if(!boss||progress.won)return;boss.t+=dt;boss.hazardTimer-=dt;const phase=boss.t%14;const dive=phase>8;const m=boss.mesh;if(phase>8&&boss.phase<=8)boss.target={x:Math.max(-18,Math.min(18,player.x)),z:Math.max(-18,Math.min(18,player.z-1.6))};boss.phase=phase;const target=dive?new T.Vector3(boss.target.x,1.8,boss.target.z):new T.Vector3(Math.cos(boss.t*.4)*13,7+Math.sin(boss.t)*1.5,Math.sin(boss.t*.4)*13);m.position.lerp(target,dt*(dive?2:1.4));m.lookAt(player.x,m.position.y,player.z);m.wings.forEach((w,i)=>w.rotation.z=Math.sin(boss.t*(dive?4:7))*.35*(i?1:-1));m.scale.lerp(new T.Vector3(1,1,1),dt*8);if(boss.hazardTimer<0&&!dive){boss.hazardTimer=2.8;const mesh=new T.Mesh(new T.RingGeometry(.15,2.3,40),new T.MeshBasicMaterial({color:'#e39894',transparent:true,opacity:.4,side:T.DoubleSide,depthWrite:false}));mesh.rotation.x=-Math.PI/2;mesh.position.set(player.x,.025,player.z);view.scene.add(mesh);hazards.push({mesh,t:1.9,x:player.x,z:player.z})}for(let i=hazards.length-1;i>=0;i--){const h=hazards[i];h.t-=dt;h.mesh.material.opacity=.35+(1.9-h.t)*.22;if(h.t<=0){if(Math.hypot(player.x-h.x,player.z-h.z)<2.3)damage(24);view.scene.remove(h.mesh);h.mesh.geometry.dispose();h.mesh.material.dispose();hazards.splice(i,1)}}$('#hint').style.display='block';$('#hint').textContent=dive?'守卫正在俯冲！靠近并用铁剑攻击':'保持移动，躲开红色落点 · 等待守卫俯冲'}
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.045);last=now;if(!view)return;if(state==='home'||state==='tour'){const a=now*.000018;view.camera.position.set(35+Math.sin(a)*4,24+Math.sin(a*.7)*1.5,42+Math.cos(a)*3);view.camera.lookAt(-3,8,-10);view.render(dt,400,false);return}if(state==='play'){elapsed+=dt;time+=dt*1200/settings.custom.dayLength;damageCooldown=Math.max(0,damageCooldown-dt);attackCooldown=Math.max(0,attackCooldown-dt);movePlayer(dt);gather(dt);if(mouseDown&&attackCooldown<=0)attack();if(progress.dimension==='overworld'){updateMobs(dt);const gateDist=Math.hypot(player.x-.5,player.z+29.5);$('#hint').style.display=gateDist<5.5?'block':'none';if(gateDist<5.5)$('#hint').textContent='F · '+(progress.inventory.sigil?'激活星门，迎接最终挑战':'星门沉睡着 · 需要星门符印')}else updateBoss(dt);saveTick+=dt;hudTick+=dt;if(hudTick>.35){hudTick=0;const hour=Math.floor((time%1200)/1200*24);$('#biome').innerHTML=(progress.dimension==='end'?'终末遗迹':'翡翠河谷')+`<span>DAY ${String(Math.floor(time/1200)+1).padStart(2,'0')} · ${String(hour).padStart(2,'0')}:00</span>`;$('#selectedname').textContent=`${items[hotbar[selected]].name} · X ${Math.floor(player.x)} / Y ${Math.floor(player.y)} / Z ${Math.floor(player.z)}`;$('#hearts').textContent='♥'.repeat(Math.ceil(progress.health/10))+'♡'.repeat(Math.max(0,10-Math.ceil(progress.health/10)));$('#foodbar').textContent='◆'.repeat(Math.ceil(progress.hunger/10))+'◇'.repeat(Math.max(0,10-Math.ceil(progress.hunger/10)));const yaw=((player.yaw*180/Math.PI)%360+360)%360;$('#compass b').textContent=yaw<45||yaw>315?'N':yaw<135?'W':yaw<225?'S':'E'}if(saveTick>15){saveTick=0;save()}}view.render(dt,time,state==='play')}
$('#start').onclick=()=>hasSave()?openPanel('new'):startNew();$('#continue').onclick=()=>{try{loadSave(JSON.parse(localStorage.getItem(SAVE)))}catch{toast('存档读取失败',true)}};document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));$('#closemodal').onclick=closePanel;$('#pausebtn').onclick=()=>openPanel('pause');$('#journalbtn').onclick=()=>openPanel('journal');$('#tour').onclick=()=>{state='tour';$('#home').hidden=true;$('#tourhud').hidden=false;$('#shade').style.opacity=0};$('#exittour').onclick=()=>{$('#tourhud').hidden=true;returnHome()};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(['Space','ArrowUp','ArrowDown','Tab'].includes(e.code))e.preventDefault();if(e.repeat){keys[e.code]=true;return}if(state==='play'){keys[e.code]=true;if(e.code==='KeyE')openPanel('inventory');else if(e.code==='KeyJ')openPanel('journal');else if(e.code==='Escape')openPanel('pause');else if(e.code==='KeyF')interact();else if(e.code==='KeyR'){player.x=progress.dimension==='end'?0:-8;player.z=progress.dimension==='end'?18:24;player.y=progress.dimension==='end'?1:world.top(-8,24)+.1;player.vy=0;toast('已返回安全地点')}else if(/^Digit[1-9]$/.test(e.code))select(+e.code.slice(5)-1)}else if(state==='paused'&&panel!=='death'&&(e.code==='Escape'||e.code==='KeyE'&&panel==='inventory'||e.code==='KeyJ'&&panel==='journal'))closePanel();else if(e.code==='Escape'&&state==='home')closePanel()});document.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={};mouseDown=false;if(state==='play')openPanel('pause')});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='play')openPanel('pause')});
let dragging=false;$('#world').addEventListener('mousedown',e=>{if(state!=='play')return;initAudio();if(e.button===0){if(document.pointerLockElement!==$('#world'))lockPointer();mouseDown=true;attack()}if(e.button===2)place();if(e.button===1){dragging=true;e.preventDefault()}});document.addEventListener('mouseup',()=>{mouseDown=false;dragging=false;mineTime=0});$('#world').addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('mousemove',e=>{if(state==='play'&&(document.pointerLockElement=== $('#world')||dragging)){player.yaw-=e.movementX*.002*settings.sensitivity;player.pitch=Math.max(-1.52,Math.min(1.52,player.pitch-e.movementY*.002*settings.sensitivity))}});document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&state==='play')openPanel('pause')});$('#world').addEventListener('wheel',e=>{if(state==='play'){e.preventDefault();select(selected+(e.deltaY>0?1:-1))}},{passive:false});window.addEventListener('beforeunload',()=>save());
async function boot(){try{await new Promise(r=>setTimeout(r,100));world=new World();$('#loadtext').textContent='河谷已经苏醒，正在铺开光影…';await new Promise(r=>setTimeout(r,30));view=new Renderer($('#world'),world,settings);initialized=true;updateHome();$('#loading').style.opacity=0;setTimeout(()=>$('#loading').hidden=true,650);requestAnimationFrame(frame)}catch(e){console.error(e);$('#loading').innerHTML='<h2>无法启动三维世界</h2><p>此游戏需要支持 WebGL 2 的电脑浏览器。请开启硬件加速后重试。</p><button class="primary" onclick="location.reload()">重新载入</button>';}}
